import React, { useEffect, useState } from "react";
import "../Styles/FindJob.css";

const FindJob = () => {
  const [jobs, setJobs] = useState([]);

  useEffect(() => {
    const storedJobs = JSON.parse(localStorage.getItem("jobs")) || [];
    setJobs(storedJobs);
  }, []);

  return (
    <div className="findjob-page">
      <h1 className="findjob-title">
        Find <span className="accent">Job</span>
      </h1>

      <div className="findjob-search">
        <input
          type="text"
          placeholder="Search skills, companies"
          className="search-input"
        />
        <button className="search-btn">Search</button>
      </div>

      <div className="job-list">
        {jobs.length === 0 ? (
          <p className="no-jobs">No jobs posted yet.</p>
        ) : (
          jobs.map((job, index) => (
            <div key={index} className="job-card">
              <div className="job-header">
                <h3>{job.jobTitle}</h3>
                <span className="rate">
                  {job.rate} OMR · {job.rateType}
                </span>
              </div>
              <p className="org-name">{job.organization}</p>
              <div className="tags">
                <span>{job.sector}</span>
                <span>{job.category}</span>
              </div>
              <p className="desc">{job.description}</p>
              <p className="skills">Skills: {job.skills}</p>
              <div className="job-actions">
                <button className="btn-details">Details</button>
                <button className="btn-apply">Apply ➜</button>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default FindJob;
